DROP POLICY IF EXISTS service_bookings_all_auth ON public.service_bookings;
CREATE POLICY service_bookings_module_read ON public.service_bookings FOR SELECT TO authenticated
  USING (public.is_admin() OR public.has_module_view('driver_management') OR public.has_module_modify('driver_management'));
CREATE POLICY service_bookings_module_write ON public.service_bookings FOR ALL TO authenticated
  USING (public.is_admin() OR public.has_module_modify('driver_management'))
  WITH CHECK (public.is_admin() OR public.has_module_modify('driver_management'));

CREATE OR REPLACE FUNCTION public.get_permissions_for_user(target_user_id uuid) ... AS $$
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'admin only' USING ERRCODE = '42501';
  END IF;
  RETURN QUERY SELECT ...;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;
REVOKE ALL ON FUNCTION public.get_permissions_for_user(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_permissions_for_user(uuid) TO authenticated;

